import { test } from "node:test";
import assert from "node:assert/strict";

import { periodRange, filterExpression, matches, summarize, localNow, colorExpression } from "../static/heatmap-data.js";

const t = (iso) => Date.parse(iso) / 1000; // local wall clock encoded as UTC
const now = t("2026-10-22T12:00:00Z");

test("periodRange for year, last 12 months, custom and all", () => {
  assert.deepEqual(periodRange({ period: "2026" }, now), [t("2026-01-01T00:00:00Z"), t("2027-01-01T00:00:00Z")]);
  assert.deepEqual(periodRange({ period: "12m" }, now), [now - 365 * 86400, Infinity]);
  assert.deepEqual(periodRange({ period: "custom", fromDate: "2026-10-01", toDate: "2026-10-05" }, now),
    [t("2026-10-01T00:00:00Z"), t("2026-10-06T00:00:00Z")]);
  assert.deepEqual(periodRange({ period: "custom", fromDate: "", toDate: "" }, now), [-Infinity, Infinity]);
  assert.deepEqual(periodRange({ period: "all" }, now), [-Infinity, Infinity]);
});

test("filterExpression omits unbounded limits", () => {
  assert.deepEqual(filterExpression({ categories: ["bike"], period: "all" }, now),
    ["all", ["in", ["get", "cat"], ["literal", ["bike"]]]]);
  const expr = filterExpression({ categories: ["bike", "run"], period: "2026" }, now);
  assert.equal(expr.length, 4);
  assert.deepEqual(expr[2], [">=", ["get", "t"], t("2026-01-01T00:00:00Z")]);
});

const features = [
  { properties: { cat: "bike", t: t("2026-10-05T10:00:00Z"), km: 24.3 } },
  { properties: { cat: "bike", t: t("2025-12-31T23:30:00Z"), km: 30.1 } },
  { properties: { cat: "hike", t: t("2026-10-04T11:00:00Z"), km: 7 } },
];

test("matches and summarize agree with the filter", () => {
  const s = { categories: ["bike"], period: "2026" };
  assert.deepEqual(features.map((f) => matches(f, s, now)), [true, false, false]);
  assert.deepEqual(summarize(features, { categories: ["bike", "hike"], period: "all" }, now), { count: 3, km: 61 });
  assert.deepEqual(summarize(features, { categories: [], period: "all" }, now), { count: 0, km: 0 });
});

test("localNow shifts by the time zone offset", () => {
  const d = { getTime: () => 1_000_000_000_000, getTimezoneOffset: () => -120 };
  assert.equal(localNow(d), 1_000_000_000 + 7200);
});

test("colorExpression", () => {
  assert.equal(colorExpression("heat", []), "#ff5722");
  assert.deepEqual(colorExpression("category", [{ id: "bike", color: "#e8590c" }]),
    ["match", ["get", "cat"], "bike", "#e8590c", "#888"]);
});
